def num_islands(grid: list[list[str]]) -> int:
    if not grid or not grid[0]:
        return 0
    # Create mutable copy to avoid modifying original input
    grid_copy = [row.copy() for row in grid]
    rows, cols = len(grid_copy), len(grid_copy[0])
    island_count = 0
    # 4-directional offsets: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(rows):
        for j in range(cols):
            if grid_copy[i][j] == "1":
                island_count += 1
                # Iterative DFS to avoid recursion limits on large grids
                stack = [(i, j)]
                grid_copy[i][j] = "#"  # Mark visited cell
                while stack:
                    x, y = stack.pop()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid_copy[nx][ny] == "1":
                            stack.append((nx, ny))
                            grid_copy[nx][ny] = "#"
    return island_count
```

