def json_escape(s: str) -> str:
    parts = ['"']
    for c in s:
        if c == '\\':
            parts.append('\\\\')
        elif c == '"':
            parts.append('\\"')
        elif c == '\n':
            parts.append('\\n')
        elif c == '\t':
            parts.append('\\t')
        elif c == '\r':
            parts.append('\\r')
        elif c == '\b':
            parts.append('\\b')
        elif c == '\f':
            parts.append('\\f')
        elif ord(c) < 0x20:
            parts.append(f'\\u{ord(c):04x}')
        else:
            parts.append(c)
    parts.append('"')
    return ''.join(parts)
```

